import{_ as e,o as r,c as d,a3 as a}from"./chunks/framework.D1iekJsc.js";const g=JSON.parse('{"title":"免費雲端","description":"MiniTavern 免費雲端 API：各廠商免費／試用額度與永久免費模型，BYOK 填寫連線；無付費 Key 時的起步方案。","frontmatter":{"title":"免費雲端","description":"MiniTavern 免費雲端 API：各廠商免費／試用額度與永久免費模型，BYOK 填寫連線；無付費 Key 時的起步方案。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"免費雲端 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern 免費雲端 API：各廠商免費／試用額度與永久免費模型，BYOK 填寫連線；無付費 Key 時的起步方案。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/free-cloud"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/free-cloud"}]]},"headers":[],"relativePath":"zh-TW/free-cloud/index.md","filePath":"zh-TW/free-cloud/index.md","lastUpdated":1787224147000}'),o={name:"zh-TW/free-cloud/index.md"};function n(i,t,l,s,h,c){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="免費雲端" tabindex="-1">免費雲端 <a class="header-anchor" href="#免費雲端" aria-label="Permalink to &quot;免費雲端&quot;">​</a></h1><p>MiniTavern 是 <strong>BYOK（自備金鑰）</strong>：不送雲端額度，需你自己註冊廠商或推理平台的 API Key。<br> 本文彙總<strong>常見免費／試用額度</strong>與填入 App 的方法；額度與政策會變動，<strong>以各官網控制台即時顯示為準</strong>。</p><blockquote><p>安全提醒：API Key 等同密碼。只填進 App 本機安全儲存，不要發到群聊、截圖公開或提交到公開倉庫。</p></blockquote><h2 id="先選一條最快路徑" tabindex="-1">先選一條最快路徑 <a class="header-anchor" href="#先選一條最快路徑" aria-label="Permalink to &quot;先選一條最快路徑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的情況</th><th>建議</th><th>App 平台</th></tr></thead><tbody><tr><td>中國大陸、想盡快開聊</td><td><a href="#智譜-ai-glm">智譜 Flash 免費模型</a> 或 <a href="#矽基流動-siliconflow">矽基流動免費模型</a></td><td>自訂 (OpenAI)</td></tr><tr><td>一個 Key 試文本 + 生圖（多模態）</td><td><a href="/ultra_guides/zh-TW/free-cloud/agnes-ai">Agnes AI</a></td><td>自訂 (OpenAI) / Images</td></tr><tr><td>一把 Key 試 GPT / Gemini 等 <code>*-free</code> + 生圖</td><td><a href="/ultra_guides/zh-TW/free-cloud/aihubmix">AIHubMix</a></td><td>自訂 (OpenAI) / Images</td></tr><tr><td>編碼向精選閘道、有限時 Free 文本</td><td><a href="/ultra_guides/zh-TW/free-cloud/opencode-zen">OpenCode Zen</a></td><td>自訂 (OpenAI)</td></tr><tr><td>想要官方中文大模型試用</td><td><a href="#通義千問--阿里雲百鍊">通義千問 · 阿里雲百鍊</a></td><td>Qwen</td></tr><tr><td>想要推理／代碼向</td><td><a href="#deepseek">DeepSeek</a></td><td>DeepSeek</td></tr><tr><td>海外帳號、多模態文本</td><td><a href="#google-gemini">Google Gemini</a></td><td>Gemini(Google)</td></tr><tr><td>一個 Key 試很多免費開源模型</td><td><a href="/ultra_guides/zh-TW/free-cloud/openrouter">OpenRouter <code>:free</code></a></td><td>OpenRouter</td></tr><tr><td>不知道還有哪些免費廠</td><td><a href="/ultra_guides/zh-TW/free-cloud/freellm">FreeLLM 目錄</a>（<a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">awesome-freellm-apis</a>）</td><td>見目錄</td></tr><tr><td>極速開源推理</td><td><a href="#groq">Groq</a></td><td>自訂 (OpenAI)</td></tr><tr><td>不想用雲端</td><td><a href="/ultra_guides/zh-TW/local/">部署本地模型</a></td><td>自訂 (OpenAI)</td></tr></tbody></table><p>填 Key 的通用步驟見 <a href="/ultra_guides/zh-TW/manual/model-link">模型連線</a>。本機部署見 <a href="/ultra_guides/zh-TW/local/">部署本地模型</a> · <a href="/ultra_guides/zh-TW/quickstart">30 分鐘通關</a>。</p><h2 id="在-minitavern-裡怎麼填" tabindex="-1">在 MiniTavern 裡怎麼填 <a class="header-anchor" href="#在-minitavern-裡怎麼填" aria-label="Permalink to &quot;在 MiniTavern 裡怎麼填&quot;">​</a></h2><p>路徑：<strong>設定 → 模型 → 模型連線 → 新建</strong></p><ol><li>選對 <strong>模型平台</strong>（下表「App 平台」欄）。</li><li>貼上 <strong>API Key</strong>；自訂平台再填 <strong>Base URL</strong>。</li><li>選擇或手填 <strong>模型 ID</strong>（必須與廠商文件一致，大小寫敏感）。</li><li>點 <strong>測試</strong> → 成功後再設為 <strong>預設</strong>。</li></ol><table tabindex="0"><thead><tr><th>廠商</th><th>App 平台</th><th>Base URL（常見）</th><th>說明</th></tr></thead><tbody><tr><td>Gemini</td><td>Gemini(Google)</td><td>預設即可</td><td>協議為 Gemini，勿當 OpenAI 填</td></tr><tr><td>OpenRouter</td><td>OpenRouter</td><td>預設即可</td><td>免費模型 ID 常帶 <code>:free</code></td></tr><tr><td>通義／百鍊</td><td>Qwen</td><td>預設（可切國際站）</td><td>Key 用<strong>通用</strong> API Key，勿用 Coding Plan 專屬 Key</td></tr><tr><td>DeepSeek</td><td>DeepSeek</td><td>預設即可</td><td></td></tr><tr><td>智譜／矽基／Agnes／AIHubMix／Zen／Groq／Mistral 等</td><td><strong>自訂 (OpenAI)</strong></td><td>見各節</td><td>OpenAI 相容閘道</td></tr></tbody></table><hr><h2 id="國內常用-大陸直連優先" tabindex="-1">國內常用（大陸直連優先） <a class="header-anchor" href="#國內常用-大陸直連優先" aria-label="Permalink to &quot;國內常用（大陸直連優先）&quot;">​</a></h2><h3 id="智譜-ai-glm" tabindex="-1">智譜 AI (GLM) <a class="header-anchor" href="#智譜-ai-glm" aria-label="Permalink to &quot;智譜 AI (GLM)&quot;">​</a></h3><p>適合：想<strong>長期免費</strong>跑通對話（Flash 系列），中文角色扮演友好。</p><table tabindex="0"><thead><tr><th>項目</th><th>說明</th></tr></thead><tbody><tr><td>官網／Key</td><td><a href="https://open.bigmodel.cn" target="_blank" rel="noreferrer">open.bigmodel.cn</a> → 控制台 → API Keys</td></tr><tr><td>免費方式</td><td><code>GLM-*-Flash</code> 等永久免費模型；新用戶常另有體驗額度（以控制台為準）</td></tr><tr><td>綁卡</td><td>通常不需要</td></tr><tr><td>Base URL</td><td><code>https://open.bigmodel.cn/api/paas/v4</code></td></tr><tr><td>模型示例</td><td><code>glm-4.5-flash</code>、<code>glm-4.7-flash</code>（名稱以模型廣場為準）</td></tr><tr><td>App</td><td><strong>自訂 (OpenAI)</strong></td></tr></tbody></table><p>步驟：註冊 → 建立 API Key → 在 App 選自訂 OpenAI → 填 Base URL 與 Key → 模型填 Flash 系列 ID → 測連。</p><h3 id="矽基流動-siliconflow" tabindex="-1">矽基流動 (SiliconFlow) <a class="header-anchor" href="#矽基流動-siliconflow" aria-label="Permalink to &quot;矽基流動 (SiliconFlow)&quot;">​</a></h3><p>適合：一個 Key 試用多種開源聊天模型；部分圖像模型也有免費檔。</p><table tabindex="0"><thead><tr><th>項目</th><th>說明</th></tr></thead><tbody><tr><td>官網／Key</td><td><a href="https://cloud.siliconflow.cn" target="_blank" rel="noreferrer">cloud.siliconflow.cn</a> → 帳戶 → API 金鑰</td></tr><tr><td>免費方式</td><td><strong>免費模型</strong>呼叫不計費（名稱不含 <code>Pro/</code> 前綴）；需完成實名後可用全部免費模型</td></tr><tr><td>限速</td><td>按模型固定 RPM/TPM；見<a href="https://docs.siliconflow.cn/cn/userguide/rate-limits/rate-limit-and-upgradation" target="_blank" rel="noreferrer">官方 Rate Limits</a></td></tr><tr><td>Base URL</td><td><code>https://api.siliconflow.cn/v1</code></td></tr><tr><td>模型示例</td><td>在模型廣場選「免費」標籤，如 <code>Qwen/Qwen3-8B</code> 等（列表會變）</td></tr><tr><td>App</td><td><strong>自訂 (OpenAI)</strong></td></tr></tbody></table><p>注意：同名模型可能有免費版與 <code>Pro/...</code> 收費版，填錯會扣費。帳單裡免費模型消耗應為 0。</p><h3 id="通義千問-·-阿里雲百鍊" tabindex="-1">通義千問 · 阿里雲百鍊 <a class="header-anchor" href="#通義千問-·-阿里雲百鍊" aria-label="Permalink to &quot;通義千問 · 阿里雲百鍊&quot;">​</a></h3><p>適合：想用官方 Qwen 系列；MiniTavern 有 <strong>Qwen</strong> 預設。</p><table tabindex="0"><thead><tr><th>項目</th><th>說明</th></tr></thead><tbody><tr><td>開通</td><td><a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">阿里雲百鍊控制台</a>（華北 2／北京）同意協議後自動開通</td></tr><tr><td>免費方式</td><td><strong>新人免費額度</strong>：多數模型約 <strong>100 萬 Token／模型</strong>，約 <strong>90 天</strong>有效；模型間額度不互通</td></tr><tr><td>Key</td><td>百鍊 → API-Key；請用<strong>通用 Key</strong>（Token Plan／Coding Plan 專屬 Key <strong>不消耗</strong>免費額度）</td></tr><tr><td>App</td><td><strong>Qwen</strong>（國內站預設；國際站可切換）</td></tr><tr><td>防扣費</td><td>控制台開啟「<strong>免費額度用完即停</strong>」，避免額度耗盡後按量扣款</td></tr></tbody></table><p>官方說明：<a href="https://help.aliyun.com/zh/model-studio/new-free-quota" target="_blank" rel="noreferrer">新人免費額度</a>。額度耗盡或過期後繼續呼叫會產生費用。</p><p>生圖（萬相／Qwen-Image 等）若參與新人額度，可在 <strong>設定 → 生圖 → 生圖連線</strong> 選 Qwen 平台；是否免費以控制台該模型額度條為準。</p><h3 id="deepseek" tabindex="-1">DeepSeek <a class="header-anchor" href="#deepseek" aria-label="Permalink to &quot;DeepSeek&quot;">​</a></h3><p>適合：推理、長文、高性價比；額度用完後很便宜，但<strong>不是永久 0 元</strong>。</p><table tabindex="0"><thead><tr><th>項目</th><th>說明</th></tr></thead><tbody><tr><td>官網／Key</td><td><a href="https://platform.deepseek.com" target="_blank" rel="noreferrer">platform.deepseek.com</a> → API Keys</td></tr><tr><td>免費方式</td><td>新用戶通常有<strong>註冊贈金／體驗額度</strong>（金額與規則以控制台為準，會調整）</td></tr><tr><td>App</td><td><strong>DeepSeek</strong></td></tr><tr><td>模型示例</td><td><code>deepseek-v4-flash</code>、<code>deepseek-v4-pro</code>（以<a href="https://api-docs.deepseek.com/zh-cn/" target="_blank" rel="noreferrer">官方文件</a>為準）</td></tr></tbody></table><p>贈金用盡後按量計費；帳戶無餘額時請求會失敗。</p><h3 id="魔搭-modelscope-api-inference" tabindex="-1">魔搭 ModelScope API-Inference <a class="header-anchor" href="#魔搭-modelscope-api-inference" aria-label="Permalink to &quot;魔搭 ModelScope API-Inference&quot;">​</a></h3><p>適合：已有阿里雲實名，想試用社群開源模型推理。</p><table tabindex="0"><thead><tr><th>項目</th><th>說明</th></tr></thead><tbody><tr><td>Token</td><td><a href="https://modelscope.cn" target="_blank" rel="noreferrer">modelscope.cn</a> → 存取權杖</td></tr><tr><td>免費方式</td><td>註冊用戶 API-Inference 有日請求配額（總量與單模型上限以<a href="https://modelscope.cn/docs/model-service/API-Inference/limits" target="_blank" rel="noreferrer">官方限額</a>為準）</td></tr><tr><td>Base URL</td><td><code>https://api-inference.modelscope.cn/v1</code></td></tr><tr><td>App</td><td><strong>自訂 (OpenAI)</strong></td></tr></tbody></table><hr><h2 id="國際-聚合平台" tabindex="-1">國際／聚合平台 <a class="header-anchor" href="#國際-聚合平台" aria-label="Permalink to &quot;國際／聚合平台&quot;">​</a></h2><h3 id="agnes-ai" tabindex="-1">Agnes AI <a class="header-anchor" href="#agnes-ai" aria-label="Permalink to &quot;Agnes AI&quot;">​</a></h3><p>適合：一個免費 Key 同時試<strong>文本對話與生圖</strong>（同屬 Flash 免費檔）；影片能力見官網，App 暫無內建影片入口。</p><p>完整介紹、模型分表與填 Key 步驟見專頁：<strong><a href="/ultra_guides/zh-TW/free-cloud/agnes-ai">Agnes AI</a></strong>。</p><table tabindex="0"><thead><tr><th>項目</th><th>說明</th></tr></thead><tbody><tr><td>官網／Key</td><td><a href="https://agnes-ai.com/" target="_blank" rel="noreferrer">agnes-ai.com</a> · <a href="https://platform.agnes-ai.com/" target="_blank" rel="noreferrer">platform.agnes-ai.com</a></td></tr><tr><td>免費方式</td><td>Free Access：Flash 文本／圖像等可免費呼叫（有 RPM 限速）</td></tr><tr><td>Base URL</td><td><code>https://apihub.agnes-ai.com/v1</code></td></tr><tr><td>文本示例</td><td><code>agnes-2.5-flash</code></td></tr><tr><td>生圖示例</td><td><code>agnes-image-2.1-flash</code>（生圖連線選 <strong>自訂 (OpenAI Images)</strong>）</td></tr><tr><td>App</td><td><strong>自訂 (OpenAI)</strong>／<strong>自訂 (OpenAI Images)</strong></td></tr></tbody></table><h3 id="opencode-zen" tabindex="-1">OpenCode Zen <a class="header-anchor" href="#opencode-zen" aria-label="Permalink to &quot;OpenCode Zen&quot;">​</a></h3><p>適合：想用 OpenCode 精選閘道上的 <strong>Free 文本模型</strong>（如 <code>mimo-v2.5-free</code>）；多數旗艦仍按量付費，注意自動儲值。</p><p>完整說明見專頁：<strong><a href="/ultra_guides/zh-TW/free-cloud/opencode-zen">OpenCode Zen</a></strong>。</p><table tabindex="0"><thead><tr><th>項目</th><th>說明</th></tr></thead><tbody><tr><td>官網／Key</td><td><a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a> · <a href="https://opencode.ai/docs/zh-cn/zen/" target="_blank" rel="noreferrer">文件</a></td></tr><tr><td>免費方式</td><td>定價表中標 Free 的模型（上限內）；其它按量付費</td></tr><tr><td>Base URL</td><td><code>https://opencode.ai/zen/v1</code></td></tr><tr><td>文本示例</td><td><code>mimo-v2.5-free</code>、<code>hy3-free</code>、<code>big-pickle</code></td></tr><tr><td>App</td><td><strong>自訂 (OpenAI)</strong>（優先 chat/completions 相容 ID）</td></tr></tbody></table><h3 id="aihubmix" tabindex="-1">AIHubMix <a class="header-anchor" href="#aihubmix" aria-label="Permalink to &quot;AIHubMix&quot;">​</a></h3><p>適合：一把 Key 試用多款平台補貼的 <code>*-free</code> 模型（含 GPT／Gemini／GLM 等）及 <strong>GPT-Image-2-free</strong> 生圖；通常無需綁卡。</p><p>完整說明見專頁：<strong><a href="/ultra_guides/zh-TW/free-cloud/aihubmix">AIHubMix</a></strong>。</p><table tabindex="0"><thead><tr><th>項目</th><th>說明</th></tr></thead><tbody><tr><td>官網／Key</td><td><a href="https://aihubmix.com" target="_blank" rel="noreferrer">aihubmix.com</a> · <a href="https://docs.aihubmix.com/cn/blogs/free-ai-models" target="_blank" rel="noreferrer">免費模型文</a></td></tr><tr><td>免費方式</td><td>模型 ID 以 <code>-free</code> 結尾；按模型 RPM／日額度</td></tr><tr><td>Base URL</td><td><code>https://aihubmix.com/v1</code></td></tr><tr><td>文本示例</td><td><code>gpt-4o-free</code>、<code>gpt-5.5-free</code>、<code>coding-glm-5.1-free</code></td></tr><tr><td>生圖示例</td><td><code>gpt-image-2-free</code>（<strong>自訂 (OpenAI Images)</strong>）</td></tr><tr><td>App</td><td><strong>自訂 (OpenAI)</strong>／<strong>自訂 (OpenAI Images)</strong></td></tr></tbody></table><h3 id="google-gemini" tabindex="-1">Google Gemini <a class="header-anchor" href="#google-gemini" aria-label="Permalink to &quot;Google Gemini&quot;">​</a></h3><p>適合：多模態文本、長上下文；<strong>文本</strong>免費檔較慷慨。</p><table tabindex="0"><thead><tr><th>項目</th><th>說明</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noreferrer">aistudio.google.com/app/apikey</a></td></tr><tr><td>免費方式</td><td>部分 Gemini Flash／Lite <strong>文本</strong>模型有 Free tier（RPM／RPD 以 AI Studio 帳戶內顯示為準）</td></tr><tr><td>綁卡</td><td>文本免費檔通常不需要；<strong>生圖類最新模型多數無 Free tier</strong></td></tr><tr><td>地區</td><td>歐盟／英國／瑞士等可能不可用免費檔</td></tr><tr><td>隱私</td><td>免費檔提示詞可能用於改進產品（見 Google 條款）</td></tr><tr><td>App</td><td><strong>Gemini(Google)</strong></td></tr></tbody></table><p>聊天請選文本模型（如 <code>gemini-flash-latest</code>）。不要選名稱帶 <code>tts</code>、<code>image</code> 的專用 ID：測連會請求文字回覆，TTS 只輸出 AUDIO，會報 <code>response modalities (TEXT) is not supported</code>。語音／生圖到對應功能裡設定。</p><p>若測連／發送返回 <code>HTTP 404</code> 且含 <code>no longer available to new users</code>：該模型 ID 已下線或不再向新用戶開放（如 <code>gemini-2.5-flash-lite</code>）。在模型連線中拉取最新列表，改選仍在線的 Flash／Lite（如 <code>gemini-flash-latest</code>）。不必改用 Interactions API。</p><p>若發送失敗提示 <code>HTTP 429</code> 且含 <code>generate_content_free_tier_requests</code>（常見 limit: 20）：這是免費檔每分鐘請求次數用盡，按 <code>Please retry in …</code> 等待後再發即可。用量見 <a href="https://ai.dev/rate-limit" target="_blank" rel="noreferrer">ai.dev/rate-limit</a>；需要更高限額可在 AI Studio 開通結算。這與「帳戶沒錢」或專案月度消費上限不同。</p><p>生圖：Gemini <strong>App</strong> 網頁端與 <strong>Developer API</strong> 額度不同；API 側圖像模型定價頁常標註 Free tier 不可用。聊天用 Gemini、生圖用本地 A1111／ComfyUI 是常見組合，見 <a href="/ultra_guides/zh-TW/local/image-gen/">生圖模型部署</a>。</p><h3 id="openrouter" tabindex="-1">OpenRouter <a class="header-anchor" href="#openrouter" aria-label="Permalink to &quot;OpenRouter&quot;">​</a></h3><p>適合：一個 Key 試用大量<strong>開源／第三方免費池</strong>；模型 ID 常以 <code>:free</code> 結尾。完整合集、分表與排錯見專頁：<strong><a href="/ultra_guides/zh-TW/free-cloud/openrouter">OpenRouter</a></strong>。</p><table tabindex="0"><thead><tr><th>項目</th><th>說明</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a></td></tr><tr><td>免費方式</td><td><code>:free</code>／合集 Free；預設可約 20 RPM、日請求有限；儲值可提高免費日限額（以官方為準）</td></tr><tr><td>App</td><td><strong>OpenRouter</strong></td></tr><tr><td>模型示例</td><td><code>openrouter/free</code>、<code>meta-llama/llama-3.3-70b-instruct:free</code>、<code>openai/gpt-oss-20b:free</code></td></tr><tr><td>合集</td><td><a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">Free Models</a> · 彙總 <a href="https://openairouter.net/free-models" target="_blank" rel="noreferrer">openairouter.net/free-models</a></td></tr></tbody></table><p>注意：免費上游可能記錄提示詞用於訓練。若 <code>HTTP 429: Provider returned error</code>：換其它 <code>:free</code>、稍後重試，或 <a href="https://openrouter.ai/settings/integrations" target="_blank" rel="noreferrer">BYOK</a>。</p><h3 id="groq" tabindex="-1">Groq <a class="header-anchor" href="#groq" aria-label="Permalink to &quot;Groq&quot;">​</a></h3><p>適合：要<strong>極低延遲</strong>的開源模型推理。</p><table tabindex="0"><thead><tr><th>項目</th><th>說明</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://console.groq.com/keys" target="_blank" rel="noreferrer">console.groq.com/keys</a></td></tr><tr><td>免費方式</td><td>永久 Free tier（按模型 RPM／RPD／TPM，會調整）</td></tr><tr><td>綁卡</td><td>通常不需要</td></tr><tr><td>Base URL</td><td><code>https://api.groq.com/openai/v1</code></td></tr><tr><td>模型示例</td><td><code>llama-3.1-8b-instant</code>、<code>llama-3.3-70b-versatile</code>、<code>openai/gpt-oss-20b</code></td></tr><tr><td>App</td><td><strong>自訂 (OpenAI)</strong></td></tr></tbody></table><h3 id="mistral-ai" tabindex="-1">Mistral AI <a class="header-anchor" href="#mistral-ai" aria-label="Permalink to &quot;Mistral AI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>說明</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://console.mistral.ai/api-keys" target="_blank" rel="noreferrer">console.mistral.ai/api-keys</a></td></tr><tr><td>免費方式</td><td>Experiment／試用計畫（月 token 量級以控制台為準）；提示詞可能用於改進</td></tr><tr><td>Base URL</td><td><code>https://api.mistral.ai/v1</code></td></tr><tr><td>App</td><td><strong>自訂 (OpenAI)</strong></td></tr></tbody></table><h3 id="cerebras-sambanova-等高速推理" tabindex="-1">Cerebras／SambaNova 等高速推理 <a class="header-anchor" href="#cerebras-sambanova-等高速推理" aria-label="Permalink to &quot;Cerebras／SambaNova 等高速推理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>平台</th><th>Key 入口</th><th>Base URL</th><th>備註</th></tr></thead><tbody><tr><td>Cerebras</td><td><a href="https://cloud.cerebras.ai/" target="_blank" rel="noreferrer">cloud.cerebras.ai</a></td><td><code>https://api.cerebras.ai/v1</code></td><td>免費檔常有日 token 上限；可能要求支付方式</td></tr><tr><td>SambaNova</td><td><a href="https://cloud.sambanova.ai/apis" target="_blank" rel="noreferrer">cloud.sambanova.ai</a></td><td><code>https://api.sambanova.ai/v1</code></td><td>永久免費檔 + 偶發贈金；限速較嚴</td></tr></tbody></table><p>App 均選 <strong>自訂 (OpenAI)</strong>，模型名以各控制台為準。</p><h3 id="github-models" tabindex="-1">GitHub Models <a class="header-anchor" href="#github-models" aria-label="Permalink to &quot;GitHub Models&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>說明</th></tr></thead><tbody><tr><td>入口</td><td><a href="https://github.com/marketplace/models" target="_blank" rel="noreferrer">GitHub Models</a></td></tr><tr><td>鑑權</td><td>GitHub Personal Access Token</td></tr><tr><td>Base URL</td><td><code>https://models.github.ai/inference</code></td></tr><tr><td>App</td><td><strong>自訂 (OpenAI)</strong></td></tr><tr><td>限制</td><td>按模型分級 RPM／RPD，適合輕量試用</td></tr></tbody></table><h3 id="nvidia-nim" tabindex="-1">NVIDIA NIM <a class="header-anchor" href="#nvidia-nim" aria-label="Permalink to &quot;NVIDIA NIM&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>說明</th></tr></thead><tbody><tr><td>入口</td><td><a href="https://build.nvidia.com/explore/discover" target="_blank" rel="noreferrer">build.nvidia.com</a></td></tr><tr><td>Base URL</td><td><code>https://integrate.api.nvidia.com/v1</code></td></tr><tr><td>App</td><td><strong>自訂 (OpenAI)</strong>（若日後 App 恢復 Nvidia 預設亦可選用）</td></tr></tbody></table><hr><h2 id="試用額度-非永久免費" tabindex="-1">試用額度（非永久免費） <a class="header-anchor" href="#試用額度-非永久免費" aria-label="Permalink to &quot;試用額度（非永久免費）&quot;">​</a></h2><p>下列多為<strong>限時贈金</strong>，適合評測，不適合當唯一長期後端：</p><table tabindex="0"><thead><tr><th>廠商</th><th>常見情況</th><th>App</th></tr></thead><tbody><tr><td>OpenAI</td><td>控制台偶發試用金；主站 API <strong>無穩定永久免費檔</strong></td><td>ChatGPT(OpenAI)</td></tr><tr><td>Anthropic Claude</td><td>控制台 starter credits，消耗快</td><td>Claude(Anthropic)</td></tr><tr><td>DeepSeek</td><td>見上文註冊贈金</td><td>DeepSeek</td></tr><tr><td>阿里雲百鍊</td><td>新人 Token 額度（約 90 天）</td><td>Qwen</td></tr></tbody></table><p>用盡後請關閉自動扣款風險（刪 Key、開「用完即停」、或改連免費模型／本地）。</p><hr><h2 id="免費生圖怎麼配" tabindex="-1">免費生圖怎麼配 <a class="header-anchor" href="#免費生圖怎麼配" aria-label="Permalink to &quot;免費生圖怎麼配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路徑</th><th>費用</th><th>說明</th></tr></thead><tbody><tr><td><a href="/ultra_guides/zh-TW/local/image-gen/">本機 A1111／ComfyUI</a></td><td>電費 + 顯示卡</td><td>不限張數；手機連電腦區域網</td></tr><tr><td>矽基流動免費圖像模型</td><td>免費模型 0 元</td><td>生圖連線選 <strong>自訂 (OpenAI Images)</strong>，Base URL 同矽基 <code>…/v1</code>，模型選免費圖像 ID</td></tr><tr><td><a href="/ultra_guides/zh-TW/free-cloud/agnes-ai">Agnes AI</a> 圖像 Flash</td><td>Free Access</td><td>生圖連線選 <strong>自訂 (OpenAI Images)</strong>，Base URL <code>https://apihub.agnes-ai.com/v1</code>，如 <code>agnes-image-2.1-flash</code></td></tr><tr><td><a href="/ultra_guides/zh-TW/free-cloud/aihubmix">AIHubMix</a></td><td><code>*-free</code> 圖像模型</td><td>生圖連線選 <strong>自訂 (OpenAI Images)</strong>，Base URL <code>https://aihubmix.com/v1</code>，如 <code>gpt-image-2-free</code></td></tr><tr><td>通義萬相／Qwen 生圖</td><td>看百鍊該模型是否有免費額度</td><td><strong>設定 → 生圖 → 生圖連線 → Qwen</strong></td></tr><tr><td>OpenAI／多數 Gemini 圖像 API</td><td>通常付費</td><td>無穩定 Free tier 時不要當「免費生圖」</td></tr></tbody></table><p>聊天模型與生圖連線可分開設定：例如聊天用智譜 Flash，生圖用家裡的 ComfyUI。</p><hr><h2 id="使用建議與排錯" tabindex="-1">使用建議與排錯 <a class="header-anchor" href="#使用建議與排錯" aria-label="Permalink to &quot;使用建議與排錯&quot;">​</a></h2><ol><li><strong>先測連再開聊</strong>：失敗時點「查看詳情」，對照 <a href="/ultra_guides/zh-TW/manual/errors">錯誤代碼排錯</a>。</li><li><strong>429／限流</strong>：換輕量模型、降記憶長度、錯峰，或再備一個免費平台。</li><li><strong>突然扣費</strong>：檢查是否用了 <code>Pro/</code> 收費模型、百鍊未開「用完即停」、或贈金已耗盡。</li><li><strong>隱私</strong>：免費檔常允許廠商用日誌改進模型；敏感內容優先 <a href="/ultra_guides/zh-TW/local/">部署本地模型</a>。</li><li><strong>額度變更</strong>：本文數字為調研時常見值；以官網為準。更全的廠商／模型索引見 <a href="/ultra_guides/zh-TW/free-cloud/freellm">FreeLLM 目錄</a>（<a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">awesome-freellm-apis</a> · <a href="https://freellm.net" target="_blank" rel="noreferrer">freellm.net</a>，非官方、每日更新）。</li></ol><h2 id="相關章節" tabindex="-1">相關章節 <a class="header-anchor" href="#相關章節" aria-label="Permalink to &quot;相關章節&quot;">​</a></h2><ul><li><a href="/ultra_guides/zh-TW/manual/model-link">模型連線</a> — App 內怎麼填</li><li><a href="/ultra_guides/zh-TW/manual/getting-started">第一次使用</a></li><li><a href="/ultra_guides/zh-TW/free-cloud/freellm">FreeLLM 目錄</a> — 更多免費廠商索引</li><li><a href="/ultra_guides/zh-TW/local/">部署本地模型</a> — 本機語言／生圖服務</li><li><a href="/ultra_guides/zh-TW/local/image-gen/">生圖模型部署</a> — A1111／ComfyUI</li></ul>',83)])])}const b=e(o,[["render",n]]);export{g as __pageData,b as default};
